import { BooleanColumn, IntegerColumn, ReferenceColumn, Table } from '../../../db'

export const sys_atf_test_suite_test = Table({
    name: 'sys_atf_test_suite_test',
    extends: 'sys_metadata',
    schema: {
        abort_on_failure: BooleanColumn({
            mandatory: false,
            label: 'Abort on failure',
            read_only: false,
            active: true,
            default: false,
        }),
        order: IntegerColumn({ mandatory: false, label: 'Execution order', read_only: false, active: true }),
        test: ReferenceColumn({
            mandatory: true,
            label: 'Test',
            read_only: false,
            active: true,
            referenceTable: 'sys_atf_test',
            cascadeRule: 'delete',
        }),
        test_suite: ReferenceColumn({
            mandatory: true,
            label: 'Test suite',
            read_only: false,
            active: true,
            referenceTable: 'sys_atf_test_suite',
            cascadeRule: 'delete',
        }),
    },
})
